import sys

ARCHIVOS = {'backend/db.py': [['        CREATE INDEX IF NOT EXISTS idx_whatsapp_envios_wamid ON whatsapp_envios(wamid);\n', '        CREATE INDEX IF NOT EXISTS idx_whatsapp_envios_wamid ON whatsapp_envios(wamid);\n        -- Asistencia: checadas del reloj checador (ZKTeco vía BioTime Pro)\n        -- y horario de cada empleado para calcular retardos y faltas.\n        CREATE TABLE IF NOT EXISTS rh_checadas (\n            id SERIAL PRIMARY KEY,\n            empresa_id INTEGER NOT NULL REFERENCES empresas(id),\n            codigo_empleado TEXT NOT NULL,\n            nombre_checador TEXT,\n            fecha_hora TIMESTAMP NOT NULL,\n            tipo TEXT,\n            dispositivo TEXT,\n            area TEXT,\n            origen TEXT NOT NULL,\n            equipo TEXT,\n            creado_en TEXT NOT NULL,\n            UNIQUE (empresa_id, codigo_empleado, fecha_hora)\n        );\n        CREATE INDEX IF NOT EXISTS idx_rh_checadas_fecha ON rh_checadas(empresa_id, fecha_hora);\n        CREATE TABLE IF NOT EXISTS rh_horarios (\n            usuario_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,\n            empresa_id INTEGER NOT NULL REFERENCES empresas(id),\n            hora_entrada TEXT NOT NULL,\n            hora_salida TEXT NOT NULL,\n            dias TEXT NOT NULL,\n            tolerancia_min INTEGER NOT NULL DEFAULT 10,\n            actualizado_en TEXT\n        );\n        ALTER TABLE empresas ADD COLUMN IF NOT EXISTS checador_token TEXT;\n        ALTER TABLE empresas ADD COLUMN IF NOT EXISTS checador_ultima_sync TEXT;\n        ALTER TABLE empresas ADD COLUMN IF NOT EXISTS checador_ultimo_equipo TEXT;\n        ALTER TABLE empresas ADD COLUMN IF NOT EXISTS checador_horario_json TEXT;\n'], ['# ---- CRM de ventas: clientes/prospectos ----\n', '# ---- Asistencia (reloj checador / BioTime) ----\n\nfrom datetime import date as _date_asis\n\ndef empresa_por_token_checador(token):\n    if not token or len(token) < 20:\n        return None\n    conn = get_connection()\n    cur = conn.cursor()\n    cur.execute("SELECT id, nombre FROM empresas WHERE checador_token = %s", (token,))\n    row = cur.fetchone()\n    cur.close(); conn.close()\n    return dict(row) if row else None\n\n\ndef config_checador(empresa_id, crear_token=False):\n    conn = get_connection()\n    cur = conn.cursor()\n    cur.execute("SELECT checador_token, checador_ultima_sync, checador_ultimo_equipo, checador_horario_json FROM empresas WHERE id = %s",\n                (empresa_id,))\n    row = dict(cur.fetchone() or {})\n    if crear_token and not row.get("checador_token"):\n        row["checador_token"] = secrets.token_urlsafe(32)\n        cur.execute("UPDATE empresas SET checador_token = %s WHERE id = %s", (row["checador_token"], empresa_id))\n        conn.commit()\n    cur.close(); conn.close()\n    try:\n        row["horario"] = json.loads(row.get("checador_horario_json") or "null")\n    except ValueError:\n        row["horario"] = None\n    return row\n\n\ndef regenerar_token_checador(empresa_id):\n    token = secrets.token_urlsafe(32)\n    conn = get_connection()\n    cur = conn.cursor()\n    cur.execute("UPDATE empresas SET checador_token = %s WHERE id = %s", (token, empresa_id))\n    conn.commit()\n    cur.close(); conn.close()\n    return token\n\n\ndef guardar_horario_default_checador(empresa_id, horario):\n    conn = get_connection()\n    cur = conn.cursor()\n    cur.execute("UPDATE empresas SET checador_horario_json = %s WHERE id = %s", (json.dumps(horario), empresa_id))\n    conn.commit()\n    cur.close(); conn.close()\n\n\ndef guardar_checadas(empresa_id, checadas, origen, equipo=None):\n    """checadas: [{codigo, nombre, fecha_hora(datetime), tipo, dispositivo, area}]. Regresa cuántas eran nuevas."""\n    if not checadas:\n        return 0\n    conn = get_connection()\n    cur = conn.cursor()\n    ts = ahora().isoformat(timespec="seconds")\n    nuevas = 0\n    for c in checadas:\n        cur.execute(\n            """INSERT INTO rh_checadas (empresa_id, codigo_empleado, nombre_checador, fecha_hora, tipo, dispositivo, area, origen, equipo, creado_en)\n               VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s)\n               ON CONFLICT (empresa_id, codigo_empleado, fecha_hora) DO NOTHING""",\n            (empresa_id, c["codigo"], (c.get("nombre") or None), c["fecha_hora"], (str(c.get("tipo"))[:40] if c.get("tipo") else None),\n             (str(c.get("dispositivo"))[:80] if c.get("dispositivo") else None), (str(c.get("area"))[:80] if c.get("area") else None),\n             origen, equipo, ts),\n        )\n        nuevas += cur.rowcount\n    conn.commit()\n    cur.close(); conn.close()\n    return nuevas\n\n\ndef marcar_sync_checador(empresa_id, equipo):\n    conn = get_connection()\n    cur = conn.cursor()\n    cur.execute("UPDATE empresas SET checador_ultima_sync = %s, checador_ultimo_equipo = %s WHERE id = %s",\n                (ahora().isoformat(timespec="seconds"), (equipo or "")[:80] or None, empresa_id))\n    conn.commit()\n    cur.close(); conn.close()\n\n\ndef listar_checadas(empresa_id, desde, hasta):\n    """desde/hasta: date (incluyentes)."""\n    conn = get_connection()\n    cur = conn.cursor()\n    cur.execute(\n        """SELECT codigo_empleado AS codigo, nombre_checador AS nombre, fecha_hora, dispositivo\n           FROM rh_checadas WHERE empresa_id = %s AND fecha_hora >= %s AND fecha_hora < %s ORDER BY fecha_hora""",\n        (empresa_id, desde, hasta + timedelta(days=1)),\n    )\n    rows = [dict(r) for r in cur.fetchall()]\n    cur.close(); conn.close()\n    return rows\n\n\ndef primera_checada(empresa_id):\n    conn = get_connection()\n    cur = conn.cursor()\n    cur.execute("SELECT MIN(fecha_hora) AS f FROM rh_checadas WHERE empresa_id = %s", (empresa_id,))\n    row = cur.fetchone()\n    cur.close(); conn.close()\n    return row["f"].date() if row and row["f"] else None\n\n\ndef empleados_asistencia(empresa_id):\n    conn = get_connection()\n    cur = conn.cursor()\n    cur.execute(\n        """SELECT u.id, u.nombre_completo AS nombre, u.numero_empleado, s.nombre AS sucursal\n           FROM users u LEFT JOIN sucursales_reparacion s ON s.id = u.sucursal_id\n           WHERE u.empresa_id = %s AND u.activo = TRUE AND COALESCE(TRIM(u.numero_empleado), \'\') <> \'\'\n           ORDER BY u.nombre_completo""",\n        (empresa_id,),\n    )\n    rows = [dict(r) for r in cur.fetchall()]\n    cur.close(); conn.close()\n    return rows\n\n\ndef horarios_asistencia(empresa_id):\n    conn = get_connection()\n    cur = conn.cursor()\n    cur.execute("SELECT usuario_id, hora_entrada, hora_salida, dias, tolerancia_min FROM rh_horarios WHERE empresa_id = %s",\n                (empresa_id,))\n    rows = {r["usuario_id"]: {k: r[k] for k in ("hora_entrada", "hora_salida", "dias", "tolerancia_min")} for r in cur.fetchall()}\n    cur.close(); conn.close()\n    return rows\n\n\ndef guardar_horario_usuario(empresa_id, usuario_id, horario):\n    conn = get_connection()\n    cur = conn.cursor()\n    if horario is None:\n        cur.execute("DELETE FROM rh_horarios WHERE usuario_id = %s AND empresa_id = %s", (usuario_id, empresa_id))\n    else:\n        cur.execute(\n            """INSERT INTO rh_horarios (usuario_id, empresa_id, hora_entrada, hora_salida, dias, tolerancia_min, actualizado_en)\n               SELECT %s, %s, %s, %s, %s, %s, %s WHERE EXISTS (SELECT 1 FROM users WHERE id = %s AND empresa_id = %s)\n               ON CONFLICT (usuario_id) DO UPDATE SET hora_entrada = EXCLUDED.hora_entrada, hora_salida = EXCLUDED.hora_salida,\n                   dias = EXCLUDED.dias, tolerancia_min = EXCLUDED.tolerancia_min, actualizado_en = EXCLUDED.actualizado_en""",\n            (usuario_id, empresa_id, horario["hora_entrada"], horario["hora_salida"], horario["dias"],\n             horario["tolerancia_min"], ahora().isoformat(timespec="seconds"), usuario_id, empresa_id),\n        )\n    conn.commit()\n    cur.close(); conn.close()\n\n\ndef incidencias_justifican_asistencia(empresa_id, desde, hasta):\n    """{usuario_id: [(desde, hasta, motivo)]} de incidencias aprobadas/pagadas y vacaciones por ajuste."""\n    conn = get_connection()\n    cur = conn.cursor()\n    cur.execute(\n        """SELECT usuario_id, tipo, fecha_inicio, fecha_fin FROM incidencias_rh\n           WHERE empresa_id = %s AND estado IN (\'aprobada\', \'pagada\')\n             AND LEFT(fecha_inicio, 10) <= %s AND LEFT(COALESCE(fecha_fin, fecha_inicio), 10) >= %s""",\n        (empresa_id, hasta.isoformat(), desde.isoformat()),\n    )\n    r = {}\n    for row in cur.fetchall():\n        try:\n            a = _date_asis.fromisoformat(str(row["fecha_inicio"])[:10])\n            b = _date_asis.fromisoformat(str(row["fecha_fin"] or row["fecha_inicio"])[:10])\n        except ValueError:\n            continue\n        r.setdefault(row["usuario_id"], []).append((a, b, f"Incidencia: {row[\'tipo\']}"))\n    cur.close(); conn.close()\n    try:\n        for v in listar_vacaciones_ajuste_empresa(empresa_id):\n            if v.get("estado") not in ("aprobada", "aprobado"):\n                continue\n            a = _date_asis.fromisoformat(str(v["fecha_inicio"])[:10])\n            b = a + timedelta(days=max(int(float(v["dias"])) - 1, 0))\n            r.setdefault(v["usuario_id"], []).append((a, b, "Vacaciones"))\n    except Exception:\n        pass\n    return r\n\n\n# ---- CRM de ventas: clientes/prospectos ----\n']], 'backend/app.py': [['import facturacion_flete\n', 'import facturacion_flete\nimport asistencia\n'], ['# ---- Ventas: clientes desde la app de iPad + WhatsApp automático (API de Meta) ----\n', '# ---- RH: Asistencia (reloj checador ZKTeco / BioTime Pro) ----\n\nclass ChecadasSyncIn(BaseModel):\n    equipo: Optional[str] = None\n    checadas: List[dict] = Field(default_factory=list, max_length=5000)\n\n\nclass ImportarChecadasIn(BaseModel):\n    archivo: str = Field(min_length=10)\n    nombre: Optional[str] = None\n\n\nclass HorarioIn(BaseModel):\n    hora_entrada: str = Field(pattern=r"^\\d{2}:\\d{2}$")\n    hora_salida: str = Field(pattern=r"^\\d{2}:\\d{2}$")\n    dias: str = Field(pattern=r"^[1-7](,[1-7])*$")\n    tolerancia_min: int = Field(ge=0, le=180)\n\n\nclass HorarioUsuarioIn(BaseModel):\n    horario: Optional[HorarioIn] = None   # None = usar el horario general\n\n\ndef _rango_fechas(desde: Optional[str], hasta: Optional[str]):\n    hoy = db.ahora().date()\n    try:\n        d = date.fromisoformat(desde) if desde else hoy - timedelta(days=hoy.weekday())\n        h = date.fromisoformat(hasta) if hasta else hoy\n    except ValueError:\n        raise HTTPException(status_code=400, detail="Fechas inválidas (usa AAAA-MM-DD).")\n    if h < d:\n        d, h = h, d\n    if (h - d).days > 92:\n        raise HTTPException(status_code=400, detail="El rango máximo es de 3 meses.")\n    return d, h\n\n\ndef _horario_default(empresa_id):\n    cfg = db.config_checador(empresa_id)\n    return {**asistencia.HORARIO_DEFAULT, **(cfg.get("horario") or {})}\n\n\ndef _reporte_asistencia(empresa_id, desde, hasta):\n    empleados = db.empleados_asistencia(empresa_id)\n    checadas = db.listar_checadas(empresa_id, desde, hasta)\n    for c in checadas:\n        c["codigo"] = asistencia.normalizar_codigo(c["codigo"])\n    justificaciones = db.incidencias_justifican_asistencia(empresa_id, desde, hasta)\n    # Vacaciones aprobadas en Microsip (si la empresa lo tiene conectado)\n    try:\n        config = db.obtener_config_microsip(empresa_id)\n        numeros = [e["numero_empleado"] for e in empleados]\n        if numeros and config and config.get("microsip_host"):\n            por_numero = {asistencia.normalizar_codigo(e["numero_empleado"]): e["id"] for e in empleados}\n            for v in microsip.obtener_vacaciones_multiples_empleados(config, numeros):\n                uid = por_numero.get(asistencia.normalizar_codigo(v.get("numero_empleado")))\n                a = asistencia.a_fecha(v.get("fecha_inicial"))\n                b = asistencia.a_fecha(v.get("fecha_fin")) or a\n                if uid and a:\n                    justificaciones.setdefault(uid, []).append((a, b, "Vacaciones (Microsip)"))\n    except Exception as e:\n        print(f"[asistencia] vacaciones de Microsip no disponibles: {e}")\n    return asistencia.calcular_reporte(empleados, checadas, db.horarios_asistencia(empresa_id),\n                                       _horario_default(empresa_id), desde, hasta, db.ahora().date(), justificaciones,\n                                       db.primera_checada(empresa_id))\n\n\n@app.post("/api/rh/checadas/sync")\ndef api_checadas_sync(payload: ChecadasSyncIn, x_token_checador: Optional[str] = Header(None)):\n    """Lo llama el programa biotime_sync.ps1 desde la PC de BioTime (sin\n    login: se identifica con el token de la empresa)."""\n    empresa = db.empresa_por_token_checador((x_token_checador or "").strip())\n    if not empresa:\n        raise HTTPException(status_code=401, detail="Token del checador inválido — descarga otra vez el programa desde RH → Asistencia.")\n    checadas = [c for c in (asistencia.checada_de_api(t) for t in payload.checadas) if c]\n    nuevas = db.guardar_checadas(empresa["id"], checadas, "biotime_pc", payload.equipo)\n    db.marcar_sync_checador(empresa["id"], payload.equipo)\n    return {"recibidas": len(payload.checadas), "validas": len(checadas), "nuevas": nuevas}\n\n\n@app.post("/api/rh/checadas/importar")\ndef api_checadas_importar(payload: ImportarChecadasIn, usuario: dict = Depends(requiere_datos_empleado_rh)):\n    if len(payload.archivo) > 20_000_000:\n        raise HTTPException(status_code=400, detail="El archivo pesa demasiado (máximo ~14MB). Exporta un rango de fechas más corto.")\n    try:\n        datos, _ = ia._decodificar_base64(payload.archivo, "application/octet-stream")\n        checadas = asistencia.leer_archivo_biotime(datos, payload.nombre or "")\n    except ValueError as e:\n        raise HTTPException(status_code=400, detail=str(e))\n    except Exception as e:\n        raise HTTPException(status_code=400, detail=f"No se pudo leer el archivo: {e}")\n    nuevas = db.guardar_checadas(usuario["empresa_id"], checadas, "archivo", payload.nombre)\n    fechas = [c["fecha_hora"] for c in checadas]\n    return {"leidas": len(checadas), "nuevas": nuevas,\n            "desde": min(fechas).date().isoformat() if fechas else None,\n            "hasta": max(fechas).date().isoformat() if fechas else None}\n\n\n@app.get("/api/rh/asistencia")\ndef api_asistencia(desde: Optional[str] = None, hasta: Optional[str] = None, usuario: dict = Depends(requiere_datos_empleado_rh)):\n    d, h = _rango_fechas(desde, hasta)\n    cfg = db.config_checador(usuario["empresa_id"])\n    return {"desde": d.isoformat(), "hasta": h.isoformat(), **_reporte_asistencia(usuario["empresa_id"], d, h),\n            "horario_general": _horario_default(usuario["empresa_id"]),\n            "ultima_sync": cfg.get("checador_ultima_sync"), "ultimo_equipo": cfg.get("checador_ultimo_equipo")}\n\n\n@app.get("/api/rh/asistencia/excel")\ndef api_asistencia_excel(desde: Optional[str] = None, hasta: Optional[str] = None, usuario: dict = Depends(requiere_datos_empleado_rh)):\n    d, h = _rango_fechas(desde, hasta)\n    empresa = db.obtener_empresa(usuario["empresa_id"]) or {}\n    contenido = asistencia.excel_reporte(_reporte_asistencia(usuario["empresa_id"], d, h), d, h, empresa.get("nombre") or "")\n    return Response(content=contenido,\n                    media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",\n                    headers={"Content-Disposition": f"attachment; filename=asistencia_{d.isoformat()}_{h.isoformat()}.xlsx"})\n\n\n@app.get("/api/rh/asistencia/config")\ndef api_asistencia_config(usuario: dict = Depends(requiere_datos_empleado_rh)):\n    cfg = db.config_checador(usuario["empresa_id"], crear_token=True)\n    return {"token": cfg.get("checador_token"), "ultima_sync": cfg.get("checador_ultima_sync"),\n            "ultimo_equipo": cfg.get("checador_ultimo_equipo"), "horario_general": _horario_default(usuario["empresa_id"])}\n\n\n@app.post("/api/rh/asistencia/token")\ndef api_asistencia_nuevo_token(usuario: dict = Depends(requiere_datos_empleado_rh)):\n    return {"token": db.regenerar_token_checador(usuario["empresa_id"])}\n\n\n@app.put("/api/rh/asistencia/horario-general")\ndef api_asistencia_horario_general(payload: HorarioIn, usuario: dict = Depends(requiere_datos_empleado_rh)):\n    db.guardar_horario_default_checador(usuario["empresa_id"], payload.model_dump())\n    return {"ok": True}\n\n\n@app.put("/api/rh/asistencia/horarios/{usuario_id}")\ndef api_asistencia_horario_usuario(usuario_id: int, payload: HorarioUsuarioIn, usuario: dict = Depends(requiere_datos_empleado_rh)):\n    db.guardar_horario_usuario(usuario["empresa_id"], usuario_id, payload.horario.model_dump() if payload.horario else None)\n    return {"ok": True}\n\n\n@app.get("/api/rh/asistencia/programa")\ndef api_asistencia_programa(request: Request, usuario: dict = Depends(requiere_datos_empleado_rh)):\n    """El programa para la PC de BioTime, ya con la dirección y el token de la empresa."""\n    cfg = db.config_checador(usuario["empresa_id"], crear_token=True)\n    base = os.getenv("APP_BASE_URL_PUBLICA") or \\\n        f"{request.headers.get(\'x-forwarded-proto\', request.url.scheme)}://{request.headers.get(\'host\', request.url.netloc)}"\n    contenido = asistencia.script_agente(base, cfg["checador_token"])\n    return Response(content=contenido.encode("utf-8-sig"), media_type="text/plain; charset=utf-8",\n                    headers={"Content-Disposition": "attachment; filename=biotime_sync.ps1"})\n\n\n# ---- Ventas: clientes desde la app de iPad + WhatsApp automático (API de Meta) ----\n']], 'frontend/index.html': [['      <button class="admin-tab" id="tabRHAusencias" onclick="cambiarRHTab(\'ausencias\')" style="display:none;">📅 Ausencias</button>\n', '      <button class="admin-tab" id="tabRHAusencias" onclick="cambiarRHTab(\'ausencias\')" style="display:none;">📅 Ausencias</button>\n      <button class="admin-tab" id="tabRHAsistencia" onclick="cambiarRHTab(\'asistencia\')" style="display:none;">⏱️ Asistencia</button>\n'], ["  document.getElementById('tabRHAusencias').style.display = esRH ? 'inline-block' : 'none';\n", "  document.getElementById('tabRHAusencias').style.display = esRH ? 'inline-block' : 'none';\n  document.getElementById('tabRHAsistencia').style.display = esRH ? 'inline-block' : 'none';\n"], ["  document.getElementById('tabRHCapacitacion').classList.toggle('active', tab === 'capacitacion');\n  if (tab === 'mishoras')", "  document.getElementById('tabRHCapacitacion').classList.toggle('active', tab === 'capacitacion');\n  document.getElementById('tabRHAsistencia').classList.toggle('active', tab === 'asistencia');\n  if (tab === 'mishoras')"], ["  else if (tab === 'capacitacion') await renderCapacitacionRH();\n", "  else if (tab === 'capacitacion') await renderCapacitacionRH();\n  else if (tab === 'asistencia') await renderAsistenciaRH();\n"], ['async function renderIncidenciasRH() {', '// ---------- RH → Asistencia (reloj checador ZKTeco / BioTime Pro) ----------\n// Checadas que llegan solas desde la PC de BioTime (programa biotime_sync.ps1)\n// o importando el archivo exportado de BioTime. Con el horario de cada\n// empleado: entrada, salida, horas, retardos y faltas (justificadas si hay\n// incidencia aprobada o vacaciones).\n\nlet ASIS = { desde: null, hasta: null, datos: null, abierto: null, filtro: \'\' };\nconst ASIS_DIAS = [[\'1\', \'L\'], [\'2\', \'M\'], [\'3\', \'Mi\'], [\'4\', \'J\'], [\'5\', \'V\'], [\'6\', \'S\'], [\'7\', \'D\']];\nconst ASIS_ESTATUS = {\n  puntual: [\'Puntual\', \'#4caf50\'], retardo: [\'Retardo\', \'#e8a33d\'], falta: [\'Falta\', \'#D8192F\'],\n  justificada: [\'Justificada\', \'#5B9BD5\'], sin_salida: [\'Sin salida\', \'#c97c2a\'], dia_no_laboral: [\'Día no laboral\', \'#888\'],\n  descanso: [\'Descanso\', \'#666\'], pendiente: [\'Pendiente\', \'#888\'],\n};\n\nfunction asis_hhmm(min) { min = Math.max(0, Math.round(min || 0)); return `${Math.floor(min / 60)}:${String(min % 60).padStart(2, \'0\')}`; }\nfunction asis_hace(iso) {\n  if (!iso) return \'nunca\';\n  const min = Math.round((Date.now() - new Date(iso).getTime()) / 60000);\n  if (isNaN(min)) return iso;\n  if (min < 2) return \'hace un momento\';\n  if (min < 60) return `hace ${min} min`;\n  if (min < 48 * 60) return `hace ${Math.round(min / 60)} h`;\n  return iso.slice(0, 16).replace(\'T\', \' \');\n}\nfunction asis_badge(est) {\n  const e = ASIS_ESTATUS[est];\n  return e ? `<span class="badge" style="background:${e[1]}; white-space:nowrap;">${e[0]}</span>` : \'\';\n}\n\nasync function renderAsistenciaRH() {\n  const cont = document.getElementById(\'rhContenido\');\n  if (!ASIS.desde) {\n    const hoy = new Date(); const lunes = new Date(hoy); lunes.setDate(hoy.getDate() - ((hoy.getDay() + 6) % 7));\n    const iso = d => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, \'0\')}-${String(d.getDate()).padStart(2, \'0\')}`;\n    ASIS.desde = iso(lunes); ASIS.hasta = iso(hoy);\n  }\n  cont.innerHTML = \'<p style="font-size:12px; color:var(--muted);">Cargando asistencia…</p>\';\n  try {\n    ASIS.datos = await api(`/api/rh/asistencia?desde=${ASIS.desde}&hasta=${ASIS.hasta}`);\n  } catch (e) {\n    cont.innerHTML = `<p style="color:var(--copper);">${escapeHtml(e.message)}</p>`;\n    return;\n  }\n  asis_pintar();\n}\n\nfunction asis_pintar() {\n  const cont = document.getElementById(\'rhContenido\');\n  const d = ASIS.datos;\n  const f = (ASIS.filtro || \'\').toLowerCase();\n  const lista = d.empleados.filter(e => !f || `${e.nombre} ${e.numero_empleado} ${e.sucursal || \'\'}`.toLowerCase().includes(f));\n  const tot = lista.reduce((t, e) => { t.r += e.resumen.retardos; t.f += e.resumen.faltas; t.j += e.resumen.justificadas; return t; }, { r: 0, f: 0, j: 0 });\n  cont.innerHTML = `\n    <div style="display:flex; gap:8px; align-items:flex-end; flex-wrap:wrap; margin-bottom:10px;">\n      <div class="field" style="margin:0;"><label>Desde</label><input type="date" id="asis_desde" value="${d.desde}" /></div>\n      <div class="field" style="margin:0;"><label>Hasta</label><input type="date" id="asis_hasta" value="${d.hasta}" /></div>\n      <button class="primary" onclick="ASIS.desde=document.getElementById(\'asis_desde\').value; ASIS.hasta=document.getElementById(\'asis_hasta\').value; renderAsistenciaRH()">Ver</button>\n      <button class="secondary" onclick="asis_excel(this)">📥 Exportar Excel</button>\n      <button class="secondary" onclick="document.getElementById(\'asis_archivo\').click()">📄 Importar archivo de BioTime</button>\n      <input id="asis_archivo" type="file" accept=".xlsx,.csv,.txt" style="display:none;" onchange="asis_importar(this)" />\n      <button class="secondary" onclick="asis_abrirHorarios()">🕘 Horarios</button>\n      <button class="secondary" onclick="asis_abrirConexion()">🔌 Conexión BioTime</button>\n    </div>\n    <div style="font-size:12px; color:var(--muted); margin-bottom:10px;">\n      Checadas automáticas desde BioTime: <b>${asis_hace(d.ultima_sync)}</b>${d.ultimo_equipo ? ` (${escapeHtml(d.ultimo_equipo)})` : \'\'}\n      · Horario general: ${d.horario_general.hora_entrada}–${d.horario_general.hora_salida}, tolerancia ${d.horario_general.tolerancia_min} min\n      · En este rango: <b style="color:#e8a33d;">${tot.r} retardos</b>, <b style="color:var(--copper);">${tot.f} faltas</b>, ${tot.j} justificadas\n    </div>\n    <div id="asis_aviso"></div>\n    ${d.codigos_sin_empleado.length ? `\n      <div class="cv-aviso" style="margin-bottom:10px; font-size:12px;">⚠️ Hay checadas de ${d.codigos_sin_empleado.length} número(s) de empleado que no corresponden a ningún usuario activo:\n        ${d.codigos_sin_empleado.slice(0, 15).map(c => `<b>${escapeHtml(c.codigo)}</b>${c.nombre ? ` (${escapeHtml(c.nombre)})` : \'\'}`).join(\', \')}${d.codigos_sin_empleado.length > 15 ? \'…\' : \'\'}.\n        Pon ese número en el campo <b>Número de empleado</b> del usuario (Administrar → Usuarios) para que se le cuenten.</div>` : \'\'}\n    <input placeholder="Buscar empleado o sucursal…" value="${escapeHtml(ASIS.filtro)}" oninput="ASIS.filtro=this.value; asis_pintarTabla()" style="max-width:320px; margin-bottom:8px;" />\n    <div id="asis_tabla"></div>`;\n  asis_pintarTabla();\n}\n\nfunction asis_pintarTabla() {\n  const d = ASIS.datos;\n  const f = (ASIS.filtro || \'\').toLowerCase();\n  const lista = d.empleados.filter(e => !f || `${e.nombre} ${e.numero_empleado} ${e.sucursal || \'\'}`.toLowerCase().includes(f));\n  document.getElementById(\'asis_tabla\').innerHTML = `\n    <table class="users">\n      <thead><tr><th>Empleado</th><th>No.</th><th>Sucursal</th><th>Días</th><th>Retardos</th><th>Faltas</th><th>Justif.</th><th>Sin salida</th><th>Horas</th><th></th></tr></thead>\n      <tbody>\n        ${lista.map(e => {\n          const r = e.resumen;\n          const abierto = ASIS.abierto === e.usuario_id;\n          return `\n          <tr>\n            <td>${escapeHtml(e.nombre)}${e.tiene_horario_propio ? \'\' : \' <span style="font-size:10px; color:var(--muted);">(horario general)</span>\'}</td>\n            <td>${escapeHtml(e.numero_empleado || \'\')}</td>\n            <td>${escapeHtml(e.sucursal || \'—\')}</td>\n            <td>${r.dias_trabajados}</td>\n            <td style="${r.retardos ? \'color:#e8a33d; font-weight:600;\' : \'\'}">${r.retardos}${r.minutos_retardo ? ` <span style="font-size:11px;">(${r.minutos_retardo} min)</span>` : \'\'}</td>\n            <td style="${r.faltas ? \'color:var(--copper); font-weight:600;\' : \'\'}">${r.faltas}</td>\n            <td>${r.justificadas}</td>\n            <td>${r.sin_salida}</td>\n            <td>${asis_hhmm(r.minutos_trabajados)}</td>\n            <td><button class="secondary" style="padding:4px 10px; font-size:11px;" onclick="ASIS.abierto=${abierto ? \'null\' : e.usuario_id}; asis_pintarTabla()">${abierto ? \'Cerrar\' : \'Ver días\'}</button></td>\n          </tr>\n          ${abierto ? `<tr><td colspan="10" style="background:rgba(155,157,159,0.07);">\n            <div style="font-size:12px; color:var(--muted); margin:4px 0 6px;">Horario: ${e.horario.hora_entrada}–${e.horario.hora_salida} · días ${String(e.horario.dias).split(\',\').map(x => (ASIS_DIAS.find(dd => dd[0] === x) || [])[1]).join(\' \')} · tolerancia ${e.horario.tolerancia_min} min</div>\n            <table class="users" style="margin:0;">\n              <thead><tr><th>Fecha</th><th>Entrada</th><th>Salida</th><th>Horas</th><th>Estatus</th><th>Checadas</th></tr></thead>\n              <tbody>${e.dias.filter(x => x.estatus).map(x => `\n                <tr>\n                  <td>${x.dia} ${x.fecha.slice(8, 10)}/${x.fecha.slice(5, 7)}</td>\n                  <td>${x.entrada || \'—\'}</td><td>${x.salida || \'—\'}</td>\n                  <td>${x.minutos ? asis_hhmm(x.minutos) : \'—\'}</td>\n                  <td>${asis_badge(x.estatus)}${x.minutos_retardo ? ` <span style="font-size:11px;">+${x.minutos_retardo} min</span>` : \'\'}${x.motivo ? ` <span style="font-size:11px; color:var(--muted);">${escapeHtml(x.motivo)}</span>` : \'\'}</td>\n                  <td style="font-size:11px; color:var(--muted);">${x.checadas.join(\', \') || \'—\'}</td>\n                </tr>`).join(\'\')}</tbody>\n            </table></td></tr>` : \'\'}`;\n        }).join(\'\') || \'<tr><td colspan="10" class="empty-col">— No hay empleados activos con número de empleado —</td></tr>\'}\n      </tbody>\n    </table>`;\n}\n\nasync function asis_excel(btn) {\n  await conBloqueoDeBoton(btn, async () => {\n    try {\n      const r = await fetch(`${API}/api/rh/asistencia/excel?desde=${ASIS.datos.desde}&hasta=${ASIS.datos.hasta}`, { headers: headers(false) });\n      if (!r.ok) throw new Error((await r.json().catch(() => ({}))).detail || \'No se pudo generar el Excel\');\n      const url = URL.createObjectURL(await r.blob());\n      const a = document.createElement(\'a\');\n      a.href = url; a.download = `asistencia_${ASIS.datos.desde}_${ASIS.datos.hasta}.xlsx`; a.click();\n      setTimeout(() => URL.revokeObjectURL(url), 2000);\n    } catch (e) { alert(e.message); }\n  });\n}\n\nfunction asis_importar(input) {\n  const file = input.files[0];\n  input.value = \'\';\n  if (!file) return;\n  const aviso = document.getElementById(\'asis_aviso\');\n  aviso.innerHTML = \'<p style="font-size:12px; color:var(--muted);">⏳ Leyendo el archivo…</p>\';\n  const lector = new FileReader();\n  lector.onload = async () => {\n    try {\n      const r = await api(\'/api/rh/checadas/importar\', { method: \'POST\', body: JSON.stringify({ archivo: lector.result, nombre: file.name }) });\n      if (r.desde && r.hasta) { ASIS.desde = r.desde; ASIS.hasta = r.hasta; }\n      await renderAsistenciaRH();\n      document.getElementById(\'asis_aviso\').innerHTML = `<p style="font-size:13px; color:#4caf50;">✔ Se leyeron ${r.leidas} checadas (${r.nuevas} nuevas) del ${r.desde || \'—\'} al ${r.hasta || \'—\'}.</p>`;\n    } catch (e) {\n      aviso.innerHTML = `<div class="cv-aviso">⚠️ ${escapeHtml(e.message)}</div>`;\n    }\n  };\n  lector.readAsDataURL(file);\n}\n\nfunction asis_htmlHorario(prefijo, h) {\n  const dias = String(h.dias || \'\').split(\',\');\n  return `\n    <input type="time" id="${prefijo}_ent" value="${h.hora_entrada}" style="width:110px;" />\n    <input type="time" id="${prefijo}_sal" value="${h.hora_salida}" style="width:110px;" />\n    <span style="display:inline-flex; gap:2px;">${ASIS_DIAS.map(([n, l]) => `<label style="font-size:11px; text-transform:none; display:inline-flex; align-items:center; gap:1px;"><input type="checkbox" class="cv-check" id="${prefijo}_d${n}" ${dias.includes(n) ? \'checked\' : \'\'} />${l}</label>`).join(\'\')}</span>\n    <input type="number" min="0" max="180" id="${prefijo}_tol" value="${h.tolerancia_min}" style="width:64px;" title="Tolerancia (min)" />`;\n}\n\nfunction asis_leerHorario(prefijo) {\n  const dias = ASIS_DIAS.map(([n]) => n).filter(n => document.getElementById(`${prefijo}_d${n}`).checked);\n  if (!dias.length) throw new Error(\'Marca al menos un día laboral.\');\n  return {\n    hora_entrada: document.getElementById(`${prefijo}_ent`).value, hora_salida: document.getElementById(`${prefijo}_sal`).value,\n    dias: dias.join(\',\'), tolerancia_min: parseInt(document.getElementById(`${prefijo}_tol`).value || \'0\', 10),\n  };\n}\n\nfunction asis_abrirHorarios() {\n  const d = ASIS.datos;\n  document.getElementById(\'modalContent\').innerHTML = `\n    <button class="close-btn" onclick="cerrarModal()">cerrar</button>\n    <h2>🕘 Horarios</h2>\n    <p style="font-size:12px; color:var(--muted);">Entrada · salida · días laborales · tolerancia en minutos (después de eso cuenta como retardo).</p>\n    <span class="cv-etq">Horario general (para quien no tenga uno propio)</span>\n    <div style="display:flex; gap:6px; align-items:center; flex-wrap:wrap;">${asis_htmlHorario(\'asis_gen\', d.horario_general)}\n      <button class="primary" onclick="asis_guardarGeneral(this)">Guardar</button></div>\n    <span class="cv-etq" style="margin-top:16px;">Por empleado</span>\n    <table class="users">\n      <thead><tr><th>Empleado</th><th>Horario</th><th></th></tr></thead>\n      <tbody>${d.empleados.slice().sort((a, b) => (a.nombre || \'\').localeCompare(b.nombre || \'\')).map(e => `\n        <tr>\n          <td>${escapeHtml(e.nombre)}<div style="font-size:10px; color:var(--muted);">${e.tiene_horario_propio ? \'Horario propio\' : \'Usa el general\'}</div></td>\n          <td style="white-space:nowrap;">${asis_htmlHorario(\'asis_u\' + e.usuario_id, e.horario)}</td>\n          <td style="white-space:nowrap;">\n            <button class="secondary" style="padding:4px 8px; font-size:11px;" onclick="asis_guardarUsuario(this, ${e.usuario_id})">Guardar</button>\n            ${e.tiene_horario_propio ? `<button class="secondary" style="padding:4px 8px; font-size:11px;" onclick="asis_quitarHorario(this, ${e.usuario_id})">Usar general</button>` : \'\'}\n          </td>\n        </tr>`).join(\'\')}</tbody>\n    </table>`;\n  abrirModal(\'admin\');\n}\n\nasync function asis_guardarGeneral(btn) {\n  await conBloqueoDeBoton(btn, async () => {\n    try {\n      await api(\'/api/rh/asistencia/horario-general\', { method: \'PUT\', body: JSON.stringify(asis_leerHorario(\'asis_gen\')) });\n      await renderAsistenciaRH(); asis_abrirHorarios();\n    } catch (e) { alert(e.message); }\n  });\n}\n\nasync function asis_guardarUsuario(btn, uid) {\n  await conBloqueoDeBoton(btn, async () => {\n    try {\n      await api(`/api/rh/asistencia/horarios/${uid}`, { method: \'PUT\', body: JSON.stringify({ horario: asis_leerHorario(\'asis_u\' + uid) }) });\n      await renderAsistenciaRH(); asis_abrirHorarios();\n    } catch (e) { alert(e.message); }\n  });\n}\n\nasync function asis_quitarHorario(btn, uid) {\n  await conBloqueoDeBoton(btn, async () => {\n    try {\n      await api(`/api/rh/asistencia/horarios/${uid}`, { method: \'PUT\', body: JSON.stringify({ horario: null }) });\n      await renderAsistenciaRH(); asis_abrirHorarios();\n    } catch (e) { alert(e.message); }\n  });\n}\n\nasync function asis_abrirConexion() {\n  document.getElementById(\'modalContent\').innerHTML = \'<p style="font-size:13px; color:var(--muted);">Cargando…</p>\';\n  abrirModal(true);\n  let c;\n  try { c = await api(\'/api/rh/asistencia/config\'); } catch (e) {\n    document.getElementById(\'modalContent\').innerHTML = `<button class="close-btn" onclick="cerrarModal()">cerrar</button><p style="color:var(--copper);">${escapeHtml(e.message)}</p>`;\n    return;\n  }\n  document.getElementById(\'modalContent\').innerHTML = `\n    <button class="close-btn" onclick="cerrarModal()">cerrar</button>\n    <h2>🔌 Conexión con BioTime</h2>\n    <p style="font-size:13px;">Última vez que llegaron checadas: <b>${asis_hace(c.ultima_sync)}</b>${c.ultimo_equipo ? ` desde <b>${escapeHtml(c.ultimo_equipo)}</b>` : \'\'}.</p>\n    <ol style="font-size:13px; line-height:1.6; padding-left:18px;">\n      <li>Descarga el programa y cópialo a la PC donde está <b>BioTime Pro</b> (por ejemplo en <code>C:\\\\biotime_sync\\\\</code>). Si cada sucursal tiene su propio BioTime, se instala en cada PC.</li>\n      <li>Ábrelo con el Bloc de notas y escribe arriba el <b>usuario y contraseña de BioTime</b> y la dirección con la que entras a BioTime en esa PC (ej. <code>http://127.0.0.1:8081</code>).</li>\n      <li>Pruébalo: abre PowerShell en esa carpeta y corre<br><code>powershell -ExecutionPolicy Bypass -File .\\\\biotime_sync.ps1</code> — debe decir <b>OK</b>.</li>\n      <li>Prográmalo cada 5 minutos (PowerShell como Administrador):<br><code style="font-size:11px;">schtasks /Create /F /SC MINUTE /MO 5 /RU SYSTEM /TN "BioTime a tickets-ti" /TR "powershell -NoProfile -ExecutionPolicy Bypass -File C:\\\\biotime_sync\\\\biotime_sync.ps1"</code></li>\n    </ol>\n    <div style="display:flex; gap:8px; flex-wrap:wrap; margin-top:10px;">\n      <button class="primary" onclick="asis_descargarPrograma(this)">⬇️ Descargar programa (biotime_sync.ps1)</button>\n      <button class="secondary" onclick="asis_nuevoToken(this)">Generar clave nueva</button>\n    </div>\n    <p style="font-size:11px; color:var(--muted); margin-top:10px;">El programa trae la clave secreta de tu empresa. "Generar clave nueva" invalida los programas ya instalados (hay que descargarlo e instalarlo otra vez).</p>`;\n}\n\nasync function asis_descargarPrograma(btn) {\n  await conBloqueoDeBoton(btn, async () => {\n    try {\n      const r = await fetch(`${API}/api/rh/asistencia/programa`, { headers: headers(false) });\n      if (!r.ok) throw new Error(\'No se pudo descargar el programa\');\n      const url = URL.createObjectURL(await r.blob());\n      const a = document.createElement(\'a\');\n      a.href = url; a.download = \'biotime_sync.ps1\'; a.click();\n      setTimeout(() => URL.revokeObjectURL(url), 2000);\n    } catch (e) { alert(e.message); }\n  });\n}\n\nasync function asis_nuevoToken(btn) {\n  if (!confirm(\'¿Generar una clave nueva? Los programas ya instalados dejarán de enviar checadas hasta que los vuelvas a descargar.\')) return;\n  await conBloqueoDeBoton(btn, async () => {\n    try { await api(\'/api/rh/asistencia/token\', { method: \'POST\' }); alert(\'Listo. Descarga el programa otra vez e instálalo en cada PC.\'); }\n    catch (e) { alert(e.message); }\n  });\n}\n\nasync function renderIncidenciasRH() {']]}

NUEVOS = {'backend/asistencia.py': '"""Asistencia (checador ZKTeco / BioTime Pro) para RH.\n\n- Las checadas llegan de dos formas:\n  1) El programa biotime_sync.ps1 que corre en la PC de BioTime (cada 5 min\n     lee la API local de BioTime y las manda a /api/rh/checadas/sync).\n  2) Importando el archivo que se exporta de BioTime (Excel o CSV).\n- Con el horario de cada empleado se calculan entrada, salida, horas,\n  retardos y faltas (las faltas con incidencia aprobada o vacaciones salen\n  como justificadas).\n"""\nimport csv\nimport io\nimport re\nimport unicodedata\nfrom datetime import date, datetime, time, timedelta\n\nHORARIO_DEFAULT = {"hora_entrada": "09:00", "hora_salida": "18:00", "dias": "1,2,3,4,5,6", "tolerancia_min": 10}\nNOMBRES_DIA = ["", "Lun", "Mar", "Mié", "Jue", "Vie", "Sáb", "Dom"]\n\n\ndef normalizar_codigo(codigo) -> str:\n    """Número de empleado comparable: sin espacios ni ceros a la izquierda."""\n    c = str(codigo or "").strip()\n    if re.fullmatch(r"\\d+(\\.0+)?", c):\n        c = c.split(".")[0].lstrip("0") or "0"\n    return c.upper()\n\n\ndef _sin_acentos(t: str) -> str:\n    return "".join(ch for ch in unicodedata.normalize("NFD", str(t or "")) if unicodedata.category(ch) != "Mn").lower().strip()\n\n\n# ---------- Fechas ----------\n\ndef a_datetime(valor, fecha_aparte=None):\n    """Convierte lo que venga del archivo/API a datetime. Formatos de México\n    (día/mes/año) cuando hay ambigüedad."""\n    if isinstance(valor, datetime):\n        return valor.replace(tzinfo=None, microsecond=0)\n    if isinstance(valor, time) and fecha_aparte is not None:\n        f = a_fecha(fecha_aparte)\n        return datetime.combine(f, valor.replace(microsecond=0)) if f else None\n    texto = str(valor or "").strip()\n    if fecha_aparte is not None and texto:\n        f = a_fecha(fecha_aparte)\n        h = _a_hora(texto)\n        return datetime.combine(f, h) if f and h else None\n    if not texto:\n        return None\n    texto = texto.replace("T", " ").split("+")[0].split(".")[0].strip()\n    texto = re.sub(r"\\s*(a\\.?\\s?m\\.?|p\\.?\\s?m\\.?)$", lambda m: " " + ("PM" if "p" in m.group(1).lower() else "AM"), texto, flags=re.I)\n    formatos = ["%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M", "%Y/%m/%d %H:%M:%S", "%Y/%m/%d %H:%M",\n                "%d/%m/%Y %H:%M:%S", "%d/%m/%Y %H:%M", "%d-%m-%Y %H:%M:%S", "%d-%m-%Y %H:%M",\n                "%d/%m/%Y %I:%M:%S %p", "%d/%m/%Y %I:%M %p", "%m/%d/%Y %I:%M:%S %p", "%m/%d/%Y %I:%M %p",\n                "%d/%m/%y %H:%M", "%d/%m/%y %H:%M:%S"]\n    for fmt in formatos:\n        try:\n            return datetime.strptime(texto, fmt)\n        except ValueError:\n            continue\n    return None\n\n\ndef a_fecha(valor):\n    if isinstance(valor, datetime):\n        return valor.date()\n    if isinstance(valor, date):\n        return valor\n    texto = str(valor or "").strip().split(" ")[0].split("T")[0]\n    for fmt in ("%Y-%m-%d", "%Y/%m/%d", "%d/%m/%Y", "%d-%m-%Y", "%d/%m/%y"):\n        try:\n            return datetime.strptime(texto, fmt).date()\n        except ValueError:\n            continue\n    return None\n\n\ndef _a_hora(valor):\n    if isinstance(valor, time):\n        return valor.replace(microsecond=0)\n    texto = str(valor or "").strip().upper()\n    for fmt in ("%H:%M:%S", "%H:%M", "%I:%M:%S %p", "%I:%M %p"):\n        try:\n            return datetime.strptime(texto, fmt).time()\n        except ValueError:\n            continue\n    return None\n\n\ndef a_minutos(hhmm: str) -> int:\n    h, m = (hhmm or "00:00").split(":")[:2]\n    return int(h) * 60 + int(m)\n\n\n# ---------- Importar archivo de BioTime ----------\n\ndef _rol_columna(encabezado: str):\n    e = _sin_acentos(encabezado)\n    e = re.sub(r"\\s+", " ", e)\n    if not e:\n        return None\n    if e in ("punch time", "hora de marcaje", "fecha y hora", "fecha/hora", "fecha hora", "marcaje",\n             "datetime", "date time", "hora de checada", "checada", "fecha de marcaje", "hora de registro") \\\n            or ("punch" in e and "time" in e) or ("marcaje" in e and "hora" in e):\n        return "fecha_hora"\n    if e in ("date", "fecha", "dia", "fecha de checada"):\n        return "fecha"\n    if e in ("time", "hora"):\n        return "hora"\n    if e in ("employee id", "emp code", "emp_code", "personnel id", "id de empleado", "id empleado",\n             "no. empleado", "no empleado", "numero de empleado", "num. empleado", "codigo", "codigo de empleado",\n             "id de personal", "id personal", "id", "no.", "ac-no.", "ac no", "user id", "id de usuario") \\\n            or ("empleado" in e and ("id" in e or "num" in e or "no" in e.split())) or ("personnel" in e and "id" in e):\n        return "codigo"\n    if e in ("first name", "nombre", "nombre(s)", "name", "nombre completo", "full name"):\n        return "nombre"\n    if e in ("last name", "apellido", "apellidos"):\n        return "apellido"\n    if e in ("punch state", "estado de marcaje", "estado", "state", "tipo de marcaje", "tipo", "estado de checada"):\n        return "tipo"\n    if e in ("device name", "terminal", "dispositivo", "nombre del dispositivo", "terminal alias", "device",\n             "alias del dispositivo", "serial number", "numero de serie", "terminal sn"):\n        return "dispositivo"\n    if e in ("area", "area name", "nombre del area", "area alias", "sucursal"):\n        return "area"\n    return None\n\n\ndef _filas_de_archivo(datos: bytes, nombre: str):\n    nombre = (nombre or "").lower()\n    if datos[:2] == b"PK" or nombre.endswith((".xlsx", ".xlsm")):\n        import openpyxl\n        libro = openpyxl.load_workbook(io.BytesIO(datos), read_only=True, data_only=True)\n        for hoja in libro.worksheets:\n            filas = [list(r) for r in hoja.iter_rows(values_only=True)]\n            if any(any(c not in (None, "") for c in f) for f in filas):\n                yield filas\n        return\n    if datos[:4] == b"\\xd0\\xcf\\x11\\xe0" or nombre.endswith(".xls"):\n        raise ValueError("Ese archivo es de Excel viejo (.xls). En BioTime expórtalo como Excel (.xlsx) o CSV.")\n    texto = None\n    for cod in ("utf-8-sig", "utf-16", "latin-1"):\n        try:\n            texto = datos.decode(cod)\n            if "\\x00" not in texto:\n                break\n        except UnicodeDecodeError:\n            continue\n    muestra = texto[:4000]\n    try:\n        dialecto = csv.Sniffer().sniff(muestra, delimiters=",;\\t|")\n    except csv.Error:\n        dialecto = csv.excel\n    yield [list(r) for r in csv.reader(io.StringIO(texto), dialecto)]\n\n\ndef leer_archivo_biotime(datos: bytes, nombre: str) -> list:\n    """Regresa [{codigo, nombre, fecha_hora (datetime), tipo, dispositivo, area}]."""\n    checadas = []\n    hubo_tabla = False\n    for filas in _filas_de_archivo(datos, nombre):\n        # El encabezado puede no estar en la primera fila (los reportes traen título)\n        idx, roles = None, None\n        for i, fila in enumerate(filas[:25]):\n            r = [_rol_columna(str(c or "")) for c in fila]\n            if "codigo" in r and ("fecha_hora" in r or ("fecha" in r and "hora" in r)):\n                idx, roles = i, r\n                break\n        if idx is None:\n            continue\n        hubo_tabla = True\n        col = {}\n        for j, rol in enumerate(roles):\n            if rol and rol not in col:\n                col[rol] = j\n        for fila in filas[idx + 1:]:\n            get = lambda k: fila[col[k]] if k in col and col[k] < len(fila) else None\n            codigo = normalizar_codigo(get("codigo"))\n            if not codigo or codigo in ("0", "NONE"):\n                continue\n            if "fecha_hora" in col:\n                fh = a_datetime(get("fecha_hora"))\n            else:\n                fh = a_datetime(get("hora"), fecha_aparte=get("fecha"))\n            if not fh:\n                continue\n            nombre_c = " ".join(str(x).strip() for x in (get("nombre"), get("apellido")) if x not in (None, ""))\n            checadas.append({\n                "codigo": codigo, "nombre": nombre_c or None, "fecha_hora": fh,\n                "tipo": (str(get("tipo")).strip() or None) if get("tipo") not in (None, "") else None,\n                "dispositivo": (str(get("dispositivo")).strip() or None) if get("dispositivo") not in (None, "") else None,\n                "area": (str(get("area")).strip() or None) if get("area") not in (None, "") else None,\n            })\n    if not hubo_tabla:\n        raise ValueError("No encontré las columnas del reporte (se necesitan al menos el número de empleado y la fecha/hora de la checada). "\n                         "En BioTime usa Asistencia → Transacciones → Exportar.")\n    return checadas\n\n\ndef checada_de_api(t: dict):\n    """Una transacción de la API de BioTime (o la que manda el programa de la PC)."""\n    codigo = normalizar_codigo(t.get("codigo") or t.get("emp_code"))\n    fh = a_datetime(t.get("fecha_hora") or t.get("punch_time"))\n    if not codigo or not fh:\n        return None\n    nombre = t.get("nombre") or " ".join(x for x in (t.get("first_name"), t.get("last_name")) if x) or None\n    return {\n        "codigo": codigo, "nombre": (str(nombre).strip() or None) if nombre else None, "fecha_hora": fh,\n        "tipo": t.get("tipo") or t.get("punch_state_display") or t.get("punch_state"),\n        "dispositivo": t.get("dispositivo") or t.get("terminal_alias") or t.get("terminal_sn"),\n        "area": t.get("area") or t.get("area_alias"),\n        "biotime_id": str(t.get("id")) if t.get("id") is not None else None,\n    }\n\n\n# ---------- Reporte ----------\n\ndef _rangos_justificados(lista):\n    """[(desde, hasta, motivo)] → función fecha → motivo|None"""\n    def buscar(d):\n        for a, b, motivo in lista:\n            if a and a <= d <= (b or a):\n                return motivo\n        return None\n    return buscar\n\n\ndef calcular_reporte(empleados, checadas, horarios, horario_default, desde: date, hasta: date, hoy: date, justificaciones,\n                     inicio_datos: date | None = None):\n    """\n    empleados: [{id, nombre, numero_empleado, sucursal}]\n    checadas: [{codigo, fecha_hora(datetime), dispositivo}]\n    horarios: {usuario_id: {hora_entrada, hora_salida, dias, tolerancia_min}}\n    justificaciones: {usuario_id: [(desde, hasta, motivo)]}\n    inicio_datos: primer día con checadas en la empresa; antes de eso no se cuentan faltas\n    """\n    por_codigo = {}\n    for c in checadas:\n        por_codigo.setdefault(c["codigo"], []).append(c)\n    codigos_empleados = {normalizar_codigo(e["numero_empleado"]): e for e in empleados if e.get("numero_empleado")}\n    sin_empleado = {}\n    for codigo, lista in por_codigo.items():\n        if codigo not in codigos_empleados:\n            sin_empleado[codigo] = {"codigo": codigo, "nombre": next((x.get("nombre") for x in lista if x.get("nombre")), None),\n                                    "checadas": len(lista)}\n\n    resultado = []\n    for e in empleados:\n        cod = normalizar_codigo(e.get("numero_empleado"))\n        h = {**horario_default, **(horarios.get(e["id"]) or {})}\n        dias_lab = {int(x) for x in str(h["dias"]).split(",") if x.strip().isdigit()}\n        tol = int(h.get("tolerancia_min") or 0)\n        ent_min, sal_min = a_minutos(h["hora_entrada"]), a_minutos(h["hora_salida"])\n        justif = _rangos_justificados(justificaciones.get(e["id"], []))\n        del_empleado = {}\n        for c in por_codigo.get(cod, []) if cod else []:\n            del_empleado.setdefault(c["fecha_hora"].date(), []).append(c)\n        dias = []\n        resumen = {"dias_trabajados": 0, "retardos": 0, "minutos_retardo": 0, "faltas": 0, "justificadas": 0,\n                   "sin_salida": 0, "minutos_trabajados": 0}\n        d = desde\n        while d <= hasta:\n            lista = sorted(del_empleado.get(d, []), key=lambda x: x["fecha_hora"])\n            laborable = d.isoweekday() in dias_lab\n            dia = {"fecha": d.isoformat(), "dia": NOMBRES_DIA[d.isoweekday()], "laborable": laborable,\n                   "checadas": [x["fecha_hora"].strftime("%H:%M") for x in lista],\n                   "entrada": None, "salida": None, "minutos": 0, "estatus": None, "minutos_retardo": 0, "motivo": None}\n            if lista:\n                entrada = lista[0]["fecha_hora"]\n                dia["entrada"] = entrada.strftime("%H:%M")\n                resumen["dias_trabajados"] += 1\n                if len(lista) > 1:\n                    salida = lista[-1]["fecha_hora"]\n                    dia["salida"] = salida.strftime("%H:%M")\n                    dia["minutos"] = int((salida - entrada).total_seconds() // 60)\n                    resumen["minutos_trabajados"] += dia["minutos"]\n                minutos_entrada = entrada.hour * 60 + entrada.minute\n                if laborable and minutos_entrada > ent_min + tol:\n                    dia["estatus"] = "retardo"\n                    dia["minutos_retardo"] = minutos_entrada - ent_min\n                    resumen["retardos"] += 1\n                    resumen["minutos_retardo"] += dia["minutos_retardo"]\n                elif not laborable:\n                    dia["estatus"] = "dia_no_laboral"\n                else:\n                    dia["estatus"] = "puntual"\n                if len(lista) == 1 and d < hoy:\n                    dia["estatus"] = dia["estatus"] if dia["estatus"] == "retardo" else "sin_salida"\n                    resumen["sin_salida"] += 1\n            elif inicio_datos and d < inicio_datos:\n                dia["estatus"] = None\n            elif laborable and d < hoy:\n                motivo = justif(d)\n                if motivo:\n                    dia["estatus"], dia["motivo"] = "justificada", motivo\n                    resumen["justificadas"] += 1\n                else:\n                    dia["estatus"] = "falta"\n                    resumen["faltas"] += 1\n            elif laborable and d == hoy:\n                dia["estatus"] = "pendiente" if datetime.now().hour * 60 < sal_min else "falta"\n                if dia["estatus"] == "falta":\n                    motivo = justif(d)\n                    if motivo:\n                        dia["estatus"], dia["motivo"] = "justificada", motivo\n                        resumen["justificadas"] += 1\n                    else:\n                        resumen["faltas"] += 1\n            else:\n                dia["estatus"] = "descanso" if not laborable else None\n            dias.append(dia)\n            d += timedelta(days=1)\n        resultado.append({\n            "usuario_id": e["id"], "nombre": e["nombre"], "numero_empleado": e.get("numero_empleado"),\n            "sucursal": e.get("sucursal"), "horario": {**h, "tolerancia_min": tol}, "tiene_horario_propio": e["id"] in horarios,\n            "resumen": resumen, "dias": dias,\n        })\n    resultado.sort(key=lambda r: (-(r["resumen"]["faltas"] + r["resumen"]["retardos"]), r["nombre"] or ""))\n    return {"empleados": resultado, "codigos_sin_empleado": sorted(sin_empleado.values(), key=lambda x: x["codigo"])}\n\n\nNOMBRES_ESTATUS = {"puntual": "Puntual", "retardo": "Retardo", "falta": "Falta", "justificada": "Justificada",\n                   "sin_salida": "Sin salida", "dia_no_laboral": "Día no laboral", "descanso": "Descanso", "pendiente": "Pendiente"}\n\n\ndef _hhmm(minutos: int) -> str:\n    return f"{minutos // 60}:{minutos % 60:02d}"\n\n\ndef excel_reporte(reporte: dict, desde: date, hasta: date, empresa: str) -> bytes:\n    import openpyxl\n    from openpyxl.styles import Font, PatternFill, Alignment\n    libro = openpyxl.Workbook()\n    negrita = Font(bold=True, color="FFFFFF")\n    relleno = PatternFill("solid", fgColor="D8192F")\n    colores = {"retardo": "FFF2CC", "falta": "F8CBAD", "justificada": "DDEBF7", "sin_salida": "FCE4D6"}\n\n    hoja = libro.active\n    hoja.title = "Resumen"\n    hoja.append([f"Asistencia {empresa} — del {desde.isoformat()} al {hasta.isoformat()}"])\n    hoja["A1"].font = Font(bold=True, size=13)\n    hoja.append([])\n    enc = ["Empleado", "No. empleado", "Sucursal", "Horario", "Días trabajados", "Retardos", "Minutos de retardo",\n           "Faltas", "Justificadas", "Sin salida", "Horas trabajadas"]\n    hoja.append(enc)\n    for c in hoja[3]:\n        c.font, c.fill = negrita, relleno\n    for e in reporte["empleados"]:\n        r, h = e["resumen"], e["horario"]\n        hoja.append([e["nombre"], e["numero_empleado"], e.get("sucursal") or "",\n                     f"{h[\'hora_entrada\']}-{h[\'hora_salida\']} (tol. {h[\'tolerancia_min\']} min)",\n                     r["dias_trabajados"], r["retardos"], r["minutos_retardo"], r["faltas"], r["justificadas"],\n                     r["sin_salida"], _hhmm(r["minutos_trabajados"])])\n    for col, ancho in zip("ABCDEFGHIJK", (32, 13, 18, 26, 15, 10, 17, 8, 12, 11, 15)):\n        hoja.column_dimensions[col].width = ancho\n\n    det = libro.create_sheet("Detalle")\n    enc = ["Empleado", "No. empleado", "Fecha", "Día", "Entrada", "Salida", "Horas", "Estatus", "Min. retardo", "Motivo", "Todas las checadas"]\n    det.append(enc)\n    for c in det[1]:\n        c.font, c.fill = negrita, relleno\n    for e in reporte["empleados"]:\n        for d in e["dias"]:\n            if not d["estatus"] or d["estatus"] == "descanso":\n                continue\n            det.append([e["nombre"], e["numero_empleado"], d["fecha"], d["dia"], d["entrada"] or "", d["salida"] or "",\n                        _hhmm(d["minutos"]) if d["minutos"] else "", NOMBRES_ESTATUS.get(d["estatus"], d["estatus"]),\n                        d["minutos_retardo"] or "", d["motivo"] or "", ", ".join(d["checadas"])])\n            color = colores.get(d["estatus"])\n            if color:\n                for c in det[det.max_row]:\n                    c.fill = PatternFill("solid", fgColor=color)\n    for col, ancho in zip("ABCDEFGHIJK", (32, 13, 12, 6, 9, 9, 8, 14, 12, 30, 40)):\n        det.column_dimensions[col].width = ancho\n    for hoja_ in (hoja, det):\n        hoja_.freeze_panes = "A4" if hoja_ is hoja else "A2"\n        for fila in hoja_.iter_rows():\n            for c in fila:\n                c.alignment = Alignment(vertical="center")\n    salida = io.BytesIO()\n    libro.save(salida)\n    return salida.getvalue()\n\n\n# ---------- Programa para la PC de BioTime ----------\n\nPLANTILLA_AGENTE = r\'\'\'# biotime_sync.ps1 -- Manda las checadas de BioTime Pro a tickets-ti.\n# Se instala en la PC donde esta BioTime. Corre cada 5 minutos con el\n# Programador de tareas de Windows (ver "Instalar" abajo). No hay que\n# abrir puertos del router: esta PC es la que se conecta a internet.\n#\n# Instalar (PowerShell como Administrador, en la carpeta de este archivo):\n#   1) Escribe abajo el usuario y contrasena de BioTime (los de entrar al\n#      BioTime por el navegador) y, si no es el puerto 80, la direccion.\n#   2) Prueba:      powershell -ExecutionPolicy Bypass -File .\\biotime_sync.ps1\n#   3) Programalo:  schtasks /Create /F /SC MINUTE /MO 5 /RU SYSTEM /TN "BioTime a tickets-ti" /TR "powershell -NoProfile -ExecutionPolicy Bypass -File \\"%RUTA%\\""\n#      (cambia %RUTA% por la ruta completa de este archivo, ej. C:\\biotime_sync\\biotime_sync.ps1)\n\n# ---- Configuracion de esta PC ----\n$BioTimeUrl      = "http://127.0.0.1:80"      # como entras a BioTime en el navegador de esta PC (ej. http://127.0.0.1:8081)\n$BioTimeUsuario  = "admin"\n$BioTimePassword = "CAMBIAR"\n$Equipo          = $env:COMPUTERNAME           # nombre con el que se ve esta PC en tickets-ti\n\n# ---- No cambiar (ya viene de tickets-ti) ----\n$TicketsUrl   = "__TICKETS_URL__"\n$TicketsToken = "__TOKEN__"\n$DiasAtras    = 3      # la primera vez manda los ultimos 3 dias; despues lo nuevo (repasa 1 dia por si un checador subio tarde)\n# -------------------------------------------\n\n$ErrorActionPreference = "Stop"\n[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12\n$Carpeta = Split-Path -Parent $MyInvocation.MyCommand.Path\nif (-not $Carpeta) { $Carpeta = (Get-Location).Path }\n$Estado  = Join-Path $Carpeta "biotime_sync_estado.txt"\n$Bitacora = Join-Path $Carpeta "biotime_sync_bitacora.txt"\n\nfunction Escribir($texto) {\n    $linea = (Get-Date -Format "yyyy-MM-dd HH:mm:ss") + "  " + $texto\n    Write-Host $linea\n    Add-Content -Path $Bitacora -Value $linea -Encoding UTF8\n}\n\nfunction Get-TokenBioTime {\n    $cuerpo = @{ username = $BioTimeUsuario; password = $BioTimePassword } | ConvertTo-Json\n    try {\n        $r = Invoke-RestMethod -Method Post -Uri ($BioTimeUrl.TrimEnd("/") + "/jwt-api-token-auth/") -ContentType "application/json" -Body $cuerpo\n        return "JWT " + $r.token\n    } catch {\n        $r = Invoke-RestMethod -Method Post -Uri ($BioTimeUrl.TrimEnd("/") + "/api-token-auth/") -ContentType "application/json" -Body $cuerpo\n        return "Token " + $r.token\n    }\n}\n\ntry {\n    if ($BioTimePassword -eq "CAMBIAR") { throw "Falta poner el usuario y contrasena de BioTime al inicio de este archivo." }\n    $ahora = Get-Date\n    $desde = $ahora.AddDays(-$DiasAtras)\n    if (Test-Path $Estado) {\n        $guardado = (Get-Content $Estado -Raw).Trim()\n        if ($guardado) { $desde = [datetime]::ParseExact($guardado, "yyyy-MM-dd HH:mm:ss", $null).AddDays(-1) }\n    }\n    $auth = Get-TokenBioTime\n    $inicio = [uri]::EscapeDataString($desde.ToString("yyyy-MM-dd HH:mm:ss"))\n    $fin = [uri]::EscapeDataString($ahora.ToString("yyyy-MM-dd HH:mm:ss"))\n    $url = $BioTimeUrl.TrimEnd("/") + "/iclock/api/transactions/?page_size=1000&start_time=$inicio&end_time=$fin"\n    $checadas = New-Object System.Collections.ArrayList\n    $paginas = 0\n    while ($url -and $paginas -lt 200) {\n        $r = Invoke-RestMethod -Method Get -Uri $url -Headers @{ Authorization = $auth }\n        $lista = $r.data\n        if ($null -eq $lista) { $lista = $r.results }\n        foreach ($t in $lista) {\n            [void]$checadas.Add(@{\n                id = $t.id; codigo = [string]$t.emp_code\n                nombre = (([string]$t.first_name + " " + [string]$t.last_name).Trim())\n                fecha_hora = [string]$t.punch_time; tipo = [string]$t.punch_state_display\n                dispositivo = [string]$(if ($t.terminal_alias) { $t.terminal_alias } else { $t.terminal_sn })\n                area = [string]$t.area_alias\n            })\n        }\n        $url = $r.next\n        $paginas++\n    }\n    $enviadas = 0; $nuevas = 0\n    for ($i = 0; $i -lt $checadas.Count; $i += 2000) {\n        $fin_lote = [Math]::Min($i + 2000, $checadas.Count) - 1\n        $lote = @($checadas[$i..$fin_lote])\n        $json = @{ equipo = $Equipo; checadas = $lote } | ConvertTo-Json -Depth 4 -Compress\n        $bytes = [System.Text.Encoding]::UTF8.GetBytes($json)\n        $r = Invoke-RestMethod -Method Post -Uri ($TicketsUrl.TrimEnd("/") + "/api/rh/checadas/sync") -ContentType "application/json; charset=utf-8" -Headers @{ "X-Token-Checador" = $TicketsToken } -Body $bytes\n        $enviadas += $lote.Count; $nuevas += [int]$r.nuevas\n    }\n    if ($checadas.Count -eq 0) {\n        $json = @{ equipo = $Equipo; checadas = @() } | ConvertTo-Json -Compress\n        $null = Invoke-RestMethod -Method Post -Uri ($TicketsUrl.TrimEnd("/") + "/api/rh/checadas/sync") -ContentType "application/json; charset=utf-8" -Headers @{ "X-Token-Checador" = $TicketsToken } -Body ([System.Text.Encoding]::UTF8.GetBytes($json))\n    }\n    Set-Content -Path $Estado -Value $ahora.ToString("yyyy-MM-dd HH:mm:ss") -Encoding ASCII\n    Escribir ("OK: " + $enviadas + " checadas revisadas, " + $nuevas + " nuevas en tickets-ti.")\n} catch {\n    Escribir ("ERROR: " + $_.Exception.Message)\n    exit 1\n}\n\'\'\'\n\n\ndef script_agente(url_tickets: str, token: str) -> str:\n    return PLANTILLA_AGENTE.replace("__TICKETS_URL__", url_tickets).replace("__TOKEN__", token).replace("\\n", "\\r\\n")\n'}


def main():
    errores = []
    cambios = {}
    for ruta, contenido in NUEVOS.items():
        if os.path.exists(ruta):
            with open(ruta, encoding="utf-8") as f:
                actual = f.read().replace("\r\n", "\n")
            if actual == contenido:
                continue
        cambios[ruta] = contenido
    for ruta, pares in ARCHIVOS.items():
        if not os.path.exists(ruta):
            errores.append(f"No encontre {ruta} -- corre el script desde la carpeta del repo.")
            continue
        with open(ruta, encoding="utf-8", newline="") as f:
            original = f.read()
        texto = original
        for i, (viejo, nuevo) in enumerate(pares, 1):
            # En Windows los archivos pueden tener saltos de linea CRLF.
            variantes = [(viejo, nuevo)]
            if "\n" in viejo:
                variantes.append((viejo.replace("\n", "\r\n"), nuevo.replace("\n", "\r\n")))
            if any(nv in texto for _, nv in variantes):
                continue  # ya aplicado
            elegido = None
            for vj, nv in variantes:
                if texto.count(vj) == 1:
                    elegido = (vj, nv)
                    break
            if not elegido:
                n = max(texto.count(vj) for vj, _ in variantes)
                errores.append(f"{ruta}: cambio #{i} -- el texto a reemplazar aparece {n} veces (se esperaba 1).")
                continue
            texto = texto.replace(elegido[0], elegido[1], 1)
        if texto != original:
            cambios[ruta] = texto
    if errores:
        print("NO se aplico nada:")
        for e in errores:
            print("  -", e)
        sys.exit(1)
    for ruta, texto in cambios.items():
        with open(ruta, "w", encoding="utf-8", newline="") as f:
            f.write(texto)
        print("Actualizado:", ruta)
    if not cambios:
        print("Todo ya estaba aplicado, no hubo cambios.")
    else:
        print("Listo.")


if __name__ == "__main__":
    main()
